import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/contribute/architecture.md","filePath":"zh/contribute/architecture.md","lastUpdated":1792800661000}'),c={name:"zh/contribute/architecture.md"};function r(s,e,i,n,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>本页概述 MeetCue 的整体结构，帮助你在修改之前找到该看的地方。</p><h2 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to &quot;概览&quot;">​</a></h2><p>MeetCue 是一个 Tauri 2 桌面应用。所有实时处理都在 Rust 端运行；React 界面只负责显示事件和发送命令。这一点很重要：WebView 被隐藏或最小化时会降低定时器频率，如果放在前端，识别和提示就会卡顿。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 麦克风 ───┐                         ┌─&gt; 语音识别（WebSocket）</span></span>
<span class="line"><span>           ├─&gt; 音频 ─&gt; 管线引擎 ─────┤</span></span>
<span class="line"><span> 系统声音 ─┘   (16 kHz)              └─&gt; 大模型（HTTPS，流式）</span></span>
<span class="line"><span>                          │</span></span>
<span class="line"><span>                          └─&gt; 事件 ─&gt; 面板与设置（React）</span></span></code></pre></div><h2 id="仓库结构" tabindex="-1">仓库结构 <a class="header-anchor" href="#仓库结构" aria-label="Permalink to &quot;仓库结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>内容</th></tr></thead><tbody><tr><td><code>crates/core</code></td><td>共享类型：设置、事件、错误码（<code>data/errors.json</code>）、价格表（<code>data/pricing.json</code>）</td></tr><tr><td><code>crates/pipeline</code></td><td>提示引擎、供应商客户端、延迟探测、练习逻辑、提示词（<code>prompts/*.txt</code>）</td></tr><tr><td><code>crates/audio</code></td><td>音频采集（Windows 上为 WASAPI）、格式转换、人声检测</td></tr><tr><td><code>crates/platform</code></td><td>凭据库、设置路径、语音合成、窗口样式</td></tr><tr><td><code>app/src-tauri</code></td><td>桌面应用：窗口、托盘、快捷键、命令、会话、诊断</td></tr><tr><td><code>app/ui</code></td><td>React 界面、翻译文件（<code>locales/</code>）、浏览器预览用的模拟后端（<code>src/mock/</code>）</td></tr><tr><td><code>docs</code></td><td>本文档站点</td></tr><tr><td><code>samples</code></td><td>为本项目编写的测试数据</td></tr></tbody></table><h2 id="管线引擎" tabindex="-1">管线引擎 <a class="header-anchor" href="#管线引擎" aria-label="Permalink to &quot;管线引擎&quot;">​</a></h2><p><code>crates/pipeline/src/engine.rs</code> 是一个同步状态机：输入（一段转写、一段模型输出、一次计时、一个用户操作）加上当前时间，返回随之产生的事件和请求。它不做任何 I/O，测试可以用假时钟一步步驱动它。</p><p><code>backend.rs</code> 负责运行引擎：持有供应商的数据流，执行请求（开始、取消或重试一次生成），并把事件转发给应用。这里保证了几条关键规则：</p><ul><li>每次生成都带版本号；被取消或过时的版本会被丢弃，其 HTTP 流会被关闭。</li><li>同时最多进行两次生成，其余排队。</li><li>问题检测只看其他与会者的声道。</li><li>转写历史只保留最近十分钟。</li></ul><h2 id="供应商" tabindex="-1">供应商 <a class="header-anchor" href="#供应商" aria-label="Permalink to &quot;供应商&quot;">​</a></h2><p>供应商接口在 <code>provider.rs</code>，各家实现在 <code>providers/</code> 目录。每个客户端处理自己的协议细节（保活、结束信号、流式格式），并按供应商返回的数据如实上报用量。金额以整数微美元计。</p><p>端点列在 <code>crates/pipeline/data/endpoints.json</code> 中，由延迟探测选择。代码里不偏向任何端点。</p><h2 id="应用与界面" tabindex="-1">应用与界面 <a class="header-anchor" href="#应用与界面" aria-label="Permalink to &quot;应用与界面&quot;">​</a></h2><ul><li>命令只在 <code>app/src-tauri/src/command_names.rs</code> 中列出一次。构建脚本、权限配置文件和 TypeScript 命令表都由测试与这份列表核对，漏掉的权限会让 CI 失败，而不是等到运行时才出错。</li><li>事件通过两个通道发出：<code>meetcue://event</code> 用于管线，<code>meetcue://app</code> 用于应用状态。</li><li>API 密钥只在 Rust 端从凭据库读取，从不传到界面。</li></ul><h2 id="错误码" tabindex="-1">错误码 <a class="header-anchor" href="#错误码" aria-label="Permalink to &quot;错误码&quot;">​</a></h2><p>每个面向用户的错误都在 <code>crates/core/data/errors.json</code> 中有错误码，以及中英两种语言的标题和解决办法。界面读取同一个文件，<code>docs/scripts/gen-errors.mjs</code> 也据此生成错误码页面，因此应用和文档不会脱节。</p>`,18)])])}const b=t(c,[["render",r]]);export{u as __pageData,b as default};
